for (const [step, pattern] of [
  ['the rail surface', /\(page, 'player-rail'\)/],
  ['the transport-footer surface', /\(page, 'transport-row'\)/],
  ['the ghost hover step', /var\(--elevate\)/],
  ['the engine-error tint', /'rgba\(0, 0, 0, 0\)'/],
]) {
